import sys

def find_n_m(x_i):
    if x_i == 0:
        return (1, 1)
    m_i = 2
    n_i = 2 * m_i - 1
    while n_i * n_i - (n_i // m_i) * (n_i // m_i) < x_i:
        m_i += 1
        n_i = 2 * m_i - 1
    return (n_i, m_i)

def main():
    t = int(sys.stdin.readline().strip())
    results = []
    for _ in range(t):
        x_i = int(sys.stdin.readline().strip())
        n_i, m_i = find_n_m(x_i)
        results.append((n_i, m_i))

    for result in results:
        print(result[0], result[1])

if __name__ == "__main__":
    main()
